      return;
    }
    const active = getConfig();
    if (next.port !== active.port || next.dataFile !== active.dataFile) {
      log.warn('config: port/dataFile changes need a restart, ignored');
    }
    current = { ...next, port: active.port, dataFile: active.dataFile };
    log.info('config reloaded', { erp_url: current.erp.url, erp_timeout_ms: current.erp.timeoutMs });
  };
  watchFile(file, { interval: options.intervalMs ?? DEFAULT_POLL_MS, persistent: false }, listener);
  return () => unwatchFile(file, listener);
}

